	@Test
	void reindexedPoscLookupSurvivesNormalCloseAndReopen(@TempDir Path storeDir) throws Exception {
		IRI subject = VF.createIRI("urn:index-rewrite:subject:17");
		IRI object = VF.createIRI("urn:index-rewrite:object:17");
		LmdbStore original = new LmdbStore(storeDir.toFile(), new LmdbStoreConfig("spoc").setForceSync(true));
		SailRepository originalRepository = new SailRepository(original);
		originalRepository.init();
		try (RepositoryConnection connection = originalRepository.getConnection()) {
			connection.add(subject, PREDICATE, object, GRAPH);
		} finally {
			originalRepository.shutDown();
		}

		LmdbStore reindexed = new LmdbStore(storeDir.toFile(), new LmdbStoreConfig("posc").setForceSync(true));
		SailRepository reindexedRepository = new SailRepository(reindexed);
		reindexedRepository.init();
		try (RepositoryConnection connection = reindexedRepository.getConnection()) {
			assertEquals(1, reindexed.getLmdbStats().tripleDatabases().get("poscposc").entries());
			assertTrue(connection.hasStatement(subject, PREDICATE, object, false));
			try (RepositoryResult<Statement> statements = connection.getStatements(subject, PREDICATE, object, false)) {
				assertTrue(statements.hasNext());
				assertEquals(GRAPH, statements.next().getContext());
			}
			assertTrue(connection.hasStatement(subject, PREDICATE, object, false, GRAPH),
					"the replacement index must resolve the record before the clean close");
		} finally {
			reindexedRepository.shutDown();
		}

		LmdbStore reopened = new LmdbStore(storeDir.toFile(), new LmdbStoreConfig().setForceSync(true));
		SailRepository reopenedRepository = new SailRepository(reopened);
		reopenedRepository.init();
		try (RepositoryConnection connection = reopenedRepository.getConnection()) {
			assertEquals(1, reopened.getLmdbStats().tripleDatabases().get("poscposc").entries());
			assertTrue(connection.hasStatement(subject, PREDICATE, object, false, GRAPH),
					"the replacement index must resolve the record after the clean close and reopen");
		} finally {
			reopenedRepository.shutDown();
		}
	}

	@Test
	@Timeout(value = 90, unit = TimeUnit.SECONDS)
	void acknowledgedCommitsSurviveChildJvmTermination(@TempDir Path workDir) throws Exception {
		Path testWorkDir = createTestWorkDir(workDir, "acknowledged");
		Path storeDir = testWorkDir.resolve("lmdb-store");
		Path witness = createExternalWitness(testWorkDir, "acknowledged-witness");
		assertFalse(witness.startsWith(storeDir), "the independent witness must be outside the LMDB directory");
		assertWitnessStoreIsIndependent(witness);

		try (ChildProcessSession child = new ChildProcessSession(startWriter(storeDir))) {
			assertEquals("READY", child.readLine(), "the child must open the real LMDB store");
			assertEquals("ROLLED_BACK", child.readLine(),
					"the known rollback must finish before acknowledged writes begin");

			acknowledgeAndContinue(child, witness, ACKNOWLEDGED_FIRST);
			acknowledgeAndContinue(child, witness, ACKNOWLEDGED_SECOND);
			assertEquals("COMMIT_RETURNED:" + ACKNOWLEDGED_FINAL.id(), child.readLine());
			appendAndForceWitness(witness, ACKNOWLEDGED_FINAL.witnessRecord());
			child.terminate();
			assertFalse(child.process.isAlive(), "only the dedicated child JVM should be terminated");
		}

		List<String> durableWitness = Files.readAllLines(witness, StandardCharsets.UTF_8);
		assertEquals(List.of(ACKNOWLEDGED_FIRST.witnessRecord(), ACKNOWLEDGED_SECOND.witnessRecord(),
				ACKNOWLEDGED_FINAL.witnessRecord()), durableWitness,
				"the controller's forced witness records the complete acknowledged payloads");
		Path preservedImage = preserveCrashImage(storeDir, "acknowledged-child-process-cut", witness);
		System.out.println("CRASH_DURABILITY_ARTIFACT:" + preservedImage);

		RecoveryState firstRecovery = reopenAndVerify(storeDir, durableWitness);
		RecoveryState secondRecovery = reopenAndVerify(storeDir, durableWitness);
		assertEquals(firstRecovery, secondRecovery,
				"every acknowledged transaction must stay present on each later reopen");
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void missingProtocolMarkerDoesNotDelayOwnedProcessCleanup() throws Exception {
		ScheduledExecutorService safetyWatchdog = Executors.newSingleThreadScheduledExecutor();
		AtomicBoolean watchdogKilledChild = new AtomicBoolean();
		try {
			try (ChildProcessSession child = new ChildProcessSession(startMissingMarkerChild())) {
				assertEquals("READY", child.readLine());
				safetyWatchdog.schedule(() -> {
					if (child.process.isAlive()) {
						watchdogKilledChild.set(true);
						child.process.destroyForcibly();
					}
				}, 4, TimeUnit.SECONDS);
				assertThrows(TimeoutException.class, () -> child.readLine(1, TimeUnit.SECONDS),
						"the missing completion marker must time out");
			}
		} finally {
			safetyWatchdog.shutdownNow();
		}
		assertFalse(watchdogKilledChild.get(), "cleanup must terminate the child before a blocked stream close");
	}

	@Test
	void recoveryOracleRejectsIncompleteOrMisindexedPayloads() {
		List<String> witness = List.of(ACKNOWLEDGED_FIRST.witnessRecord(), ACKNOWLEDGED_SECOND.witnessRecord(),
				ACKNOWLEDGED_FINAL.witnessRecord());
		Set<Statement> complete = acknowledgedStatements();
		verifyRecoveryOracle(complete, witness, ACKNOWLEDGED_FINAL.namespaceValue());

		Set<Statement> missingAcknowledgedPayload = new LinkedHashSet<>(complete);
		missingAcknowledgedPayload.remove(ACKNOWLEDGED_FIRST.additions().get(1));
		assertOracleRejects(missingAcknowledgedPayload, witness, ACKNOWLEDGED_FINAL.namespaceValue(),
				"a missing acknowledged statement");

		Set<Statement> partialUnknown = new LinkedHashSet<>(complete);
		partialUnknown.add(ATOMICITY_PROBE.additions().get(0));
		assertThrows(AssertionError.class,
				() -> verifyAtomicTransactionOutcome(complete, ACKNOWLEDGED_FINAL.namespaceValue(), ATOMICITY_PROBE,
						partialUnknown, ACKNOWLEDGED_FINAL.namespaceValue(), Map.of(), null),
				"a partial in-progress transaction must be rejected");
		verifyAtomicTransactionOutcome(complete, ACKNOWLEDGED_FINAL.namespaceValue(), MIXED_DELETE_REPLACEMENT,
				complete, ACKNOWLEDGED_FINAL.namespaceValue(), Map.of(), null);
		Set<Statement> replacementOnly = new LinkedHashSet<>(complete);
		replacementOnly.add(REPLACEMENT_STATEMENT);
		assertThrows(AssertionError.class,
				() -> verifyAtomicTransactionOutcome(complete, ACKNOWLEDGED_FINAL.namespaceValue(),
						MIXED_DELETE_REPLACEMENT, replacementOnly, ACKNOWLEDGED_FINAL.namespaceValue(), Map.of(), null),
				"the new value without the delete must be rejected");
		Set<Statement> deletionOnly = new LinkedHashSet<>(complete);
		deletionOnly.remove(ACKNOWLEDGED_SECOND.additions().get(0));
		assertThrows(AssertionError.class,
				() -> verifyAtomicTransactionOutcome(complete, ACKNOWLEDGED_FINAL.namespaceValue(),
						MIXED_DELETE_REPLACEMENT, deletionOnly, ACKNOWLEDGED_FINAL.namespaceValue(), Map.of(), null),
				"the delete without the replacement must be rejected");
		verifyAtomicTransactionOutcome(complete, ACKNOWLEDGED_FINAL.namespaceValue(), MIXED_DELETE_REPLACEMENT,
				applyTransaction(complete, MIXED_DELETE_REPLACEMENT), ACKNOWLEDGED_FINAL.namespaceValue(), Map.of(),
				null);

		Set<Statement> wrongType = new LinkedHashSet<>(complete);
		wrongType.removeIf(statement -> statement.getSubject().equals(SUBJECT)
				&& statement.getObject().equals(VF.createLiteral("second acknowledged generation")));
		wrongType.add(VF.createStatement(SUBJECT, PREDICATE, VF.createLiteral(42), (Resource) null));
		assertOracleRejects(wrongType, witness, ACKNOWLEDGED_FINAL.namespaceValue(), "a value with the wrong type");

		Set<Statement> wrongContext = new LinkedHashSet<>(complete);
		Statement namedState = ACKNOWLEDGED_SECOND.additions().get(1);
		wrongContext.remove(namedState);
		wrongContext.add(VF.createStatement(namedState.getSubject(), namedState.getPredicate(), namedState.getObject(),
				(Resource) null));
		assertOracleRejects(wrongContext, witness, ACKNOWLEDGED_FINAL.namespaceValue(),
				"a statement in the wrong context");

		Set<Statement> resurrectedDelete = new LinkedHashSet<>(complete);
		resurrectedDelete.add(REMOVED_ACKNOWLEDGED_STATEMENT);
		assertOracleRejects(resurrectedDelete, witness, ACKNOWLEDGED_FINAL.namespaceValue(),
				"a deleted statement resurrected during recovery");
		assertThrows(AssertionError.class,
				() -> verifyRecoveryOracle(complete, witness.subList(0, witness.size() - 1),
						ACKNOWLEDGED_FINAL.namespaceValue()),
				"an acknowledgment omitted from the external witness must be rejected");
	}

	@Test
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void legacyNamespaceMigrationKeepsEmptyAuthorityOverStaleFile(@TempDir Path workDir) throws Exception {
		Path fixtureRoot = workDir.resolve("legacy-fixture");
		extractLegacyStoreFixture(fixtureRoot);
		Path storeDir = fixtureRoot.resolve("store");
		Path namespacesFile = storeDir.resolve("namespaces.dat");
		byte[] legacyNamespaces = Files.readAllBytes(namespacesFile);

		LmdbStore store = new LmdbStore(storeDir.toFile(), durableConfig());
		store.init();
		try (SailConnection connection = store.getConnection()) {
			assertEquals(ACKNOWLEDGED_FINAL.namespaceValue(), connection.getNamespace("crash"),
					"opening a store without the new authority marker must import its legacy namespace file");
			connection.begin(IsolationLevels.SNAPSHOT);
			connection.removeNamespace("crash");
			connection.commit();
		} finally {
			store.shutDown();
		}

		Files.write(namespacesFile, legacyNamespaces, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING,
				StandardOpenOption.WRITE);
		LmdbStore reopened = new LmdbStore(storeDir.toFile(), durableConfig());
		reopened.init();
		try (SailConnection connection = reopened.getConnection()) {
			assertNull(connection.getNamespace("crash"),
					"an authoritative empty namespace snapshot must prevent stale legacy-file resurrection");
		} finally {
			reopened.shutDown();
		}
	}

	@Test
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void largeMultibyteNamespacePrefixAndValueSurviveReopen(@TempDir Path storeDir) throws Exception {
		String prefix = "prefix:" + "p".repeat(4096);
		String namespace = "urn:long:" + "å".repeat(33_000);
		LmdbStore store = new LmdbStore(storeDir.toFile(), durableConfig());
		store.init();
		try (SailConnection connection = store.getConnection()) {
			connection.begin(IsolationLevels.SNAPSHOT);
			connection.setNamespace(prefix, namespace);
			connection.commit();
			assertEquals(namespace, connection.getNamespace(prefix));
		} finally {
			store.shutDown();
		}

		LmdbStore reopened = new LmdbStore(storeDir.toFile(), durableConfig());
		reopened.init();
		try (SailConnection connection = reopened.getConnection()) {
			assertEquals(namespace, connection.getNamespace(prefix),
					"LMDB namespace persistence must support values larger than a page and prefixes larger than a key");
			Map<String, String> namespacePairs = new LinkedHashMap<>();
			try (var namespaces = connection.getNamespaces()) {
				while (namespaces.hasNext()) {
					Namespace current = namespaces.next();
					assertNull(namespacePairs.put(current.getPrefix(), current.getName()),
							"namespace iteration must not emit duplicates");
				}
			}
			assertEquals(Map.of(prefix, namespace), namespacePairs,
					"namespace iteration must return the complete multibyte prefix/value pair");
		} finally {
			reopened.shutDown();
		}
	}

	@Test
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void namespaceOnlyAcknowledgmentUsesAuthoritativeTripleStoreCommit(@TempDir Path storeDir) throws Exception {
		InspectableLmdbStore store = new InspectableLmdbStore(storeDir, durableConfig());
		store.init();
		try {
			long transactionIdBefore = store.lastTripleTransactionId();
			long dataRevisionBefore = store.tripleStore().getDataRevision();
			try (SailConnection connection = store.getConnection()) {
				connection.begin(IsolationLevels.SNAPSHOT);
				connection.setNamespace("only", "urn:namespace:only:");
				connection.commit();
			}
			assertTrue(store.lastTripleTransactionId() > transactionIdBefore,
					"the namespace ACK must follow a physical forced TripleStore transaction");
			assertEquals(dataRevisionBefore, store.tripleStore().getDataRevision(),
					"namespace publication must not advance the triple revision used by retirement GC");
		} finally {
			store.shutDown();
		}

		LmdbStore reopened = new LmdbStore(storeDir.toFile(), durableConfig());
		reopened.init();
		try (SailConnection connection = reopened.getConnection()) {
			assertEquals("urn:namespace:only:", connection.getNamespace("only"));
		} finally {
			reopened.shutDown();
		}
	}

