	@Test
	@Timeout(value = 60, unit = TimeUnit.SECONDS)
	void successfulNativeCommitReceiptAvoidsNamespaceReadReconciliation(@TempDir Path storeDir) throws Exception {
		PostCommitFailureLmdbStore store = new PostCommitFailureLmdbStore(storeDir, durableConfig());
		store.init();
		store.failAfterNativeCommit();
		try (SailConnection connection = store.getConnection()) {
			connection.begin(IsolationLevels.SNAPSHOT);
			connection.setNamespace("receipt", "urn:namespace:receipt:");
			addStatement(connection, VF.createStatement(SUBJECT, PREDICATE, VF.createLiteral("receipt marker")));
			assertThrows(SailException.class, connection::commit,
					"the injected post-commit exception remains visible to the caller");
		}
		try (SailConnection connection = store.getConnection()) {
			assertEquals("urn:namespace:receipt:", connection.getNamespace("receipt"),
					"an acknowledged native namespace commit must not fence the live store when reconciliation reads fail");
		} finally {
			store.shutDown();
		}

		LmdbStore reopened = new LmdbStore(storeDir.toFile(), durableConfig());
		reopened.init();
		try (SailConnection connection = reopened.getConnection()) {
			assertEquals("urn:namespace:receipt:", connection.getNamespace("receipt"),
					"the native commit must remain authoritative after a post-commit exception");
		} finally {
			reopened.shutDown();
		}
	}

